-- Etapa 5. Leitura; escopos geral e delivered se sobrepõem.
WITH b AS (SELECT x.order_id,x.order_status order_status,dt.dia dia_compra,date_trunc('month',dt.dia)::date mes,l.customer_state uf,l.customer_city cidade,l.membro_tipo localizacao_tipo,x.payment_sequential,x.payment_value,m.payment_type payment_type FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario dt ON dt.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_forma_pagamento m ON m.forma_pagamento_sk=x.forma_pagamento_sk), a AS (SELECT 'geral'::text escopo,b.* FROM b UNION ALL SELECT 'delivered',b.* FROM b WHERE order_status='delivered') SELECT escopo,localizacao_tipo,uf,cidade,count(*) linhas,count(DISTINCT order_id) pedidos,sum(payment_value) payment_value FROM a GROUP BY escopo,localizacao_tipo,uf,cidade;
